import React, { useEffect, useState } from 'react';

const MinimalPortfolio = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [isDesktop, setIsDesktop] = useState(false);
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    document.title = 'Ranvir.';
    const timer = setTimeout(() => setIsVisible(true), 100);

    const handleResize = () => {
      setIsDesktop(window.innerWidth >= 768);
    };

    handleResize();
    window.addEventListener('resize', handleResize);

    return () => {
      clearTimeout(timer);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  // Full-screen wrapper style (background applied here)
  const wrapperStyles = {
    background: darkMode
      ? 'linear-gradient(90deg, #1C093F 0%, #0C0F33 100%)'
      : '#f9f9f9',
    minHeight: '100vh',
    transition: 'background 0.3s ease, color 0.3s ease',
    display: 'flex',
    justifyContent: 'center',
  };

  // Inner container style (content is centered and limited in width)
  const containerStyles = {
    color: darkMode ? '#ffffff' : '#000000',
    fontFamily: "'SF Pro Display', sans-serif",
    fontWeight: 500,
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    padding: '0 20px',
    maxWidth: isDesktop ? '800px' : '600px',
    transition: 'opacity 1s ease-in',
    position: 'relative',
    opacity: isVisible ? 1 : 0,
  };

  return (
    <div style={wrapperStyles}>
      <div style={containerStyles}>
        {/* Dark Mode Toggle */}
        <div
          style={{
            position: 'absolute',
            top: '20px',
            right: '20px',
            fontSize: '0.9rem',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
          }}
        >
          <input
            type="checkbox"
            checked={darkMode}
            onChange={() => setDarkMode(prev => !prev)}
            style={{ marginRight: '8px' }}
          />
          Dark Mode
        </div>

        <h2
          style={{
            fontSize: isDesktop ? '48px' : '32px',
            margin: '0 0 10px 0',
            fontWeight: 500,
          }}
        >
          Ranvir Deshmukh
        </h2>
        <h3
          style={{
            fontSize: isDesktop ? '24px' : '20px',
            margin: '0 0 25px 0',
            opacity: 0.8,
          }}
        >
          I write software and make videos.
        </h3>

        <p
          style={{
            fontSize: isDesktop ? '18px' : '16px',
            lineHeight: '1.6',
            marginBottom: '30px',
          }}
        >
          I’m currently building{' '}
          <a
            href="https://courseme.ai"
            target="_blank"
            rel="noopener noreferrer"
            style={{
              textDecoration: 'none',
              color: darkMode ? '#c792ea' : '#571ce0',
              fontWeight: 600,
            }}
          >
            CourseMe
          </a>
          <span style={{ color: '#FD5E53', fontWeight: 600 }}>.</span> <br />
          Studying Computer Science at{' '}
          <a
            href="https://home.dartmouth.edu/"
            target="_blank"
            rel="noopener noreferrer"
            style={{
              textDecoration: 'none',
              color: darkMode ? '#8bc34a' : '#00693e',
              fontWeight: 600,
            }}
          >
            Dartmouth
          </a>
          . <br />
          Reach out — I’m always open to chat!
        </p>

        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '8px',
            marginBottom: '40px',
          }}
        >
          <a
            href="https://www.linkedin.com/in/ranvir-deshmukh-209706199/"
            style={{
              textDecoration: 'none',
              color: darkMode ? '#ffffff' : '#000000',
              fontWeight: 500,
            }}
            target="_blank"
            rel="noopener noreferrer"
          >
            LinkedIn
          </a>
          <span style={{ color: darkMode ? '#ffffff' : '#000000', opacity: 0.6 }}>
            |
          </span>
          <a
            href="https://github.com/Ranvirdeshmukh"
            style={{
              textDecoration: 'none',
              color: darkMode ? '#ffffff' : '#000000',
              fontWeight: 500,
            }}
            target="_blank"
            rel="noopener noreferrer"
          >
            GitHub
          </a>
        </div>

        <div
          style={{
            marginTop: '40px',
            fontSize: isDesktop ? '16px' : '14px',
            fontWeight: 600,
            color: darkMode ? '#cccccc' : '#999999',
            opacity: 0.8,
            alignSelf: 'flex-start',
          }}
        >
          RD/&gt;
        </div>
      </div>
    </div>
  );
};

export default MinimalPortfolio;
